        "description": "\" 난치성질환 치료기업 다임바이오 김정민 대표가 항암제 'DM5167'의 효능과 안전성 입증에 성공해시리즈B투자 유치를 수월하게 마무리하고 있다고 밝혔다. DNA 손상 복구에 관여하는 PARP 1·2를 동시 억제하는 기존 1세대 약물과 달리 PARP1만 선택 저해해 전체 혈액독성(All grade) 발생률을 15%, 3등급 이상...새 창 열림",
